mapper.update:
UPDATE APP_USER
   SET LOGIN_FAIL_COUNT = 0, LAST_LOGIN_AT = #{now}
 WHERE USER_ID = #{userId}

UPDATE APP_USER
   SET LOGIN_FAIL_COUNT = #{failCount}

     , ACCOUNT_STATUS_CODE = 'LOCKED', LOCKED_AT = #{now}, LOCK_REASON = '비밀번호 5회 연속 실패'

     , UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}

UPDATE APP_USER
   SET PASSWORD_HASH = #{passwordHash}, LOGIN_FAIL_COUNT = 0,
       ACCOUNT_STATUS_CODE = CASE WHEN ACCOUNT_STATUS_CODE = 'LOCKED' THEN 'ACTIVE' ELSE ACCOUNT_STATUS_CODE END,
       LOCKED_AT = NULL, LOCK_REASON = NULL, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND ACCOUNT_STATUS_CODE <> 'WITHDRAWN'

UPDATE APP_USER
   SET PASSWORD_HASH = #{passwordHash}, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}

UPDATE APP_USER
   SET EMAIL_ENC = #{emailEnc}, EMAIL_HMAC = #{emailHmac}, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}

UPDATE APP_USER
   SET WORKER_TYPE_CODE = #{workerTypeCode}, UPDATED_AT = #{now}
 WHERE USER_ID = #{userId}
   AND WORKER_TYPE_CODE IS NULL
